begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values('11111111-1111-4111-8111-111111111111','owner@example.invalid',now()),('22222222-2222-4222-8222-222222222222','other@example.invalid',now());
create temporary table fixture(key text primary key,id uuid);
grant all on fixture to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
insert into fixture values('brand',public.create_owner_workspace('Owner','Analytics brand','UTC','','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true));
insert into fixture values('source',public.register_brand_source((select id from fixture where key='brand'),'gsc','Search','sc-domain:example.invalid'));
reset role;
update public.brand_sources set state='authorized',provider_timezone='America/Los_Angeles',verified_account='sc-domain:example.invalid',version=2 where id=(select id from fixture where key='source');
insert into private.connector_credentials(source_id,brand_id,encrypted_value,key_version,expires_at) values((select id from fixture where key='source'),(select id from fixture where key='brand'),'test-only','test',now()+interval '1 hour');
set local role authenticated;
insert into fixture values('run',public.request_source_sync((select id from fixture where key='brand'),(select id from fixture where key='source'),gen_random_uuid()));
select is((select kind from public.collection_runs),'gsc_daily','Google source queues matching adapter');
select is((select range_end-range_start from public.collection_runs),27,'Backfill has exactly 28 dates');
select throws_ok($$insert into public.analytics_days(brand_id,source_id,observed_date,provider,provider_timezone,state,metrics,run_id) values((select id from fixture where key='brand'),(select id from fixture where key='source'),current_date,'gsc','America/Los_Angeles','available','{"clicks":999}',(select id from fixture where key='run'))$$,'42501',null,'Clients cannot fabricate analytics');
reset role;
insert into public.analytics_days(brand_id,source_id,observed_date,provider,provider_timezone,state,metrics,run_id) values((select id from fixture where key='brand'),(select id from fixture where key='source'),current_date,'gsc','America/Los_Angeles','available','{"clicks":0}',(select id from fixture where key='run'));
select throws_ok($$insert into public.analytics_days(brand_id,source_id,observed_date,provider,provider_timezone,state,metrics,run_id) values((select id from fixture where key='brand'),(select id from fixture where key='source'),current_date-1,'gsc','America/Los_Angeles','unavailable','{"clicks":0}',(select id from fixture where key='run'))$$,'23514',null,'Unavailable analytics cannot be stored as zero metrics');
set local role authenticated;
insert into fixture values('report',public.create_client_report((select id from fixture where key='brand'),gen_random_uuid(),'Captured analytics',current_date,current_date,'Test only'));
select is((select snapshot->'analytics_days'->0->'metrics'->>'clicks' from public.client_reports),'0','Report preserves explicit measured zero');
reset role;
update public.analytics_days set metrics='{"clicks":12}';
set local role authenticated;
select is((select snapshot->'analytics_days'->0->'metrics'->>'clicks' from public.client_reports),'0','Later analytics refresh does not rewrite report');
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
select is((select count(*)::int from public.analytics_days),0,'Unrelated tenant cannot read daily metrics');
select is((select count(*)::int from public.client_reports),0,'Unrelated tenant cannot read measurements through snapshots');
reset role;
select * from finish();
rollback;
